mapper.sql:
p.ctrt_bgn_dt <= #{lastDate} AND p.ctrt_end_dt >= #{firstDate}
AND p.ctrt_type_cd=#{filter.contractType}
AND p.effective_status=#{filter.status}
AND (strpos(p.proj_nm,#{filter.q}) > 0 OR strpos(p.customer_name,#{filter.q}) > 0)

mapper.select:
SELECT 'ACT:'||asgn_id AS target,to_char(input_bgn_dt,'YYYY-MM') AS month FROM tb_pj_asgn WHERE proj_id=#{id} AND asgn_stat_cd='ACT' AND input_bgn_dt<#{startDate}
UNION ALL SELECT 'ACT:'||asgn_id,to_char(input_end_dt,'YYYY-MM') FROM tb_pj_asgn WHERE proj_id=#{id} AND asgn_stat_cd='ACT' AND input_end_dt>#{endDate}
UNION ALL SELECT '배분표:'||dstrb_step_cd,substring(dstrb_ym,1,4)||'-'||substring(dstrb_ym,5,2) FROM tb_pj_tk_dstrb WHERE proj_id=#{id} AND (dstrb_ym<to_char(CAST(#{startDate} AS date),'YYYYMM') OR dstrb_ym>to_char(CAST(#{endDate} AS date),'YYYYMM'))
UNION ALL SELECT '영업 파트',substring(aply_bgn_ym,1,4)||'-'||substring(aply_bgn_ym,5,2) FROM tb_pj_proj_part WHERE proj_id=#{id} AND aply_bgn_ym<>#{firstMonth} AND (aply_bgn_ym<=to_char(CAST(#{startDate} AS date),'YYYYMM') OR aply_bgn_ym>to_char(CAST(#{endDate} AS date),'YYYYMM'))
